import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';

// استيراد الصفحات
import Landing from './pages/Landing';
import Login from './pages/Login';
import Registration from './pages/Registration';
import Sidebar from './components/Sidebar';
import StudentDashboard from './pages/StudentDashboard';
import StudentProfile from './pages/StudentProfile';
import MyApplications from './pages/MyApplications';
import StudentOffers from './pages/StudentOffers';
// تأكد من إنشاء هذه الصفحة واستيرادها هنا
 import OfferDetails from './pages/OfferDetails'; 
 import SearchOffers from './pages/SearchOffers';

function App() {
  return (
    <Router>
      <Routes>
        <Route path="/" element={<Landing />} />
        <Route path="/login" element={<Login />} />
        <Route path="/register" element={<Registration />} />
 <Route path="/" element={<Registration />} />
        <Route path="/student/*" element={
          <div className="flex min-h-screen bg-slate-50" dir="rtl">
            <main className="flex-1 mr-64 p-8">
              <Routes>
                <Route path="dashboard" element={<StudentDashboard />} />
                <Route path="profile" element={<StudentProfile />} />
                <Route path="applications" element={<MyApplications />} />
                <Route path="search" element={<StudentOffers />} />
                <Route path="offer/:id" element={<OfferDetails />} />
                {/* السطر الناقص الذي يجعل "عرض التفاصيل" يعمل */}
                <Route path="offer/:id" element={<div>هنا تظهر تفاصيل العرض</div>} />
                {/* بمجرد تجهيز صفحة التفاصيل، استبدلها بـ: <Route path="offer/:id" element={<OfferDetails />} /> */}
              </Routes>
            </main>
            <Sidebar />
          </div>
        } />
      </Routes>
    </Router>
  );
}

export default App;
